action.command:
node -e "
const t=require('/tmp/tree.json');
const paths = t.tree.map(x=>x.path).filter(p=>p.endsWith('.properties') && !p.includes('login/messages'));
console.log(paths.slice(0,40).join('\n'));
console.log('---total properties:', paths.length);
console.log('truncated:', t.truncated);
" 2>&1

